using Repricing.Execution;
using Repricing.Storage;
namespace Repricing.Tests;
public class IncomePriorityTests
{
 sealed class Client:IZiniaoPriceCutClient
 {
  public List<string> Calls=[];public decimal? NormalNet=59,PreviewNet=61;public bool Capped,Disconnect,Changed,Stale,OrdinaryExitThrows;
  public ZiniaoProduct Product=new("456","SKU-A","商品","R$ 100",[new("P-1","平台补贴","激活","R$ 70",true,false,NetAmountText:"R$ 60"),new("C-1","普通活动","已预约","R$ 75",false,true,NetAmountText:"R$ 58")]);
  public Task<ZiniaoStore[]> StoresAsync(CancellationToken ct)=>Task.FromResult(new[]{new ZiniaoStore("123","测试","MercadoLibre-巴西")});
  public Task<ZiniaoProduct[]> ReadAsync(ZiniaoStore s,PriceInput i,CancellationToken ct){Calls.Add("read");return Task.FromResult(new[]{Changed&&Calls.Count(x=>x=="read")>1?Product with{BasePriceText="R$ 110"}:Product});}
  public Task<decimal?> PreviewNetAsync(PriceCutPlan p,CancellationToken ct){Calls.Add("preview");return Task.FromResult(PreviewNet);}
  public Task PrepareAsync(PriceCutPlan p,CancellationToken ct){Calls.Add("prepare");if(Capped&&!p.Join)throw new AppException("平台活动价上限为 R$ 75；未提交。",422);return Task.CompletedTask;}
  public Task SubmitAsync(PriceCutPlan p,CancellationToken ct){Calls.Add("save");if(!Stale)Product=Product with{Promotions=Product.Promotions.Select(x=>x.Id=="C-1"?x with{PriceText="R$ 80",Status="已预约",Editable=true,Joinable=false,NetAmountText=NormalNet==null?null:$"R$ {NormalNet:0.00}".Replace('.',',')}:x).ToArray()};if(Disconnect)throw new IOException();return Task.CompletedTask;}
  public Task PrepareExitAsync(PriceCutPlan p,CancellationToken ct){Calls.Add("prepare-exit");Assert.True(ZiniaoIncomeExecutor.Valid(p));return Task.CompletedTask;}
  public Task ConfirmExitAsync(PriceCutPlan p,CancellationToken ct){if(p.Stage=="income-ordinary-exit"){Calls.Add("exit-ordinary");Product=Product with{Promotions=Product.Promotions.Select(x=>x.Id=="C-1"?x with{Active=false,Editable=false,Joinable=true,Status=""}:x).ToArray()};if(OrdinaryExitThrows)throw new IOException();}else{Calls.Add("exit");Product=Product with{Promotions=Product.Promotions.Select(x=>x.Id=="P-1"?x with{Active=false}:x with{Active=true,Status="激活"}).ToArray()};}return Task.CompletedTask;}
  public Task<ZiniaoProduct> VerifyAsync(PriceCutPlan p,CancellationToken ct)=>Task.FromResult(Product);
 }
 static PriceInput Input()=>new("123","MLB","BRL","SKU-A",null,null,null,80,null,true,false,null);
 static Task<ExecutionResult> Run(Client c,PriceCutPlan? previous=null,Action<PriceCutPlan>? checkpoint=null)=>new ZiniaoPriceCutExecutor(c).ExecuteAsync(Input(),p=>{c.Calls.Add("checkpoint-"+p.Stage);checkpoint?.Invoke(p);},default,previous,allowIncrease:true,allowBaseChange:true,incomePriority:true);
 [Theory][InlineData(59)][InlineData(60)] public async Task LowerOrEqualTargetPreviewKeepsSubsidyWithoutChangingOffer(decimal net){var c=new Client{NormalNet=net,PreviewNet=net};var r=await Run(c);Assert.Equal("subsidy-preview-kept",r.Checkpoint);Assert.Equal(RowStatus.Skipped,r.Status);Assert.DoesNotContain("save",c.Calls);Assert.DoesNotContain("exit",c.Calls);Assert.DoesNotContain("exit-ordinary",c.Calls);}
 [Fact] public async Task BetterActualOrdinaryExitsOnlyAfterReporting(){var c=new Client{NormalNet=61};var r=await Run(c);Assert.Equal(RowStatus.Succeeded,r.Status);Assert.True(c.Calls.IndexOf("save")<c.Calls.IndexOf("exit"));Assert.True(c.Calls.IndexOf("checkpoint-income-exit")<c.Calls.IndexOf("exit"));}
 [Fact] public async Task CapRejoinsOrdinaryBeforeComparingActualTargetNet(){var c=new Client{Capped=true,NormalNet=61};var r=await Run(c);Assert.Equal(RowStatus.Succeeded,r.Status);Assert.True(c.Calls.IndexOf("exit-ordinary")<c.Calls.IndexOf("save"));Assert.True(c.Calls.IndexOf("save")<c.Calls.IndexOf("exit"));}
 [Fact] public async Task MissingPreviewNeverExitsAnyCampaign(){var c=new Client{PreviewNet=null,Capped=true};Assert.Equal(RowStatus.NeedsReview,(await Run(c)).Status);Assert.DoesNotContain("save",c.Calls);Assert.DoesNotContain("exit-ordinary",c.Calls);Assert.DoesNotContain("exit",c.Calls);}
 [Fact] public async Task UnknownOrdinaryExitResumesJoinWithoutRepeatingExit(){var c=new Client{Capped=true,NormalNet=61,OrdinaryExitThrows=true};PriceCutPlan? saved=null;Assert.True((await Run(c,checkpoint:p=>saved=p)).Retryable);Assert.Equal("income-ordinary-exit",saved!.Stage);c.Calls.Clear();c.OrdinaryExitThrows=false;Assert.Equal(RowStatus.Succeeded,(await Run(c,saved)).Status);Assert.DoesNotContain("exit-ordinary",c.Calls);Assert.Single(c.Calls,x=>x=="save");}
 [Fact] public async Task MissingActualNetNeverExits(){var c=new Client{NormalNet=null};Assert.Equal(RowStatus.NeedsReview,(await Run(c)).Status);Assert.DoesNotContain("exit",c.Calls);}
 [Fact] public async Task ChangedReadbackNeverExits(){var c=new Client{NormalNet=61,Changed=true};Assert.Equal(RowStatus.NeedsReview,(await Run(c)).Status);Assert.DoesNotContain("exit",c.Calls);}
 [Fact] public async Task SavedUnknownReconcilesWithoutSecondSubmission(){var c=new Client{Disconnect=true,NormalNet=61};PriceCutPlan? saved=null;Assert.True((await Run(c,checkpoint:p=>saved=p)).Retryable);c.Calls.Clear();Assert.Equal(RowStatus.Succeeded,(await Run(c,saved)).Status);Assert.DoesNotContain("save",c.Calls);Assert.DoesNotContain("prepare",c.Calls);Assert.Contains("exit",c.Calls);}
 [Fact] public async Task ExitCheckpointFailurePreventsExit(){var c=new Client{NormalNet=61};await Run(c,checkpoint:p=>{if(p.Stage=="income-exit")throw new IOException();});Assert.DoesNotContain("exit",c.Calls);}
 [Fact] public async Task UnknownExitCannotBecomeTerminalKeepWhenNetChanges(){var c=new Client{NormalNet=61};PriceCutPlan? saved=null;await Run(c,checkpoint:p=>{saved=p;if(p.Stage=="income-exit")throw new IOException();});c.Product=c.Product with{Promotions=c.Product.Promotions.Select(x=>x.Id=="P-1"?x with{NetAmountText="R$ 65"}:x).ToArray()};c.Calls.Clear();var r=await Run(c,saved);Assert.Equal(RowStatus.NeedsReview,r.Status);Assert.True(r.Retryable);Assert.DoesNotContain("save",c.Calls);Assert.DoesNotContain("exit",c.Calls);}
 [Fact] public async Task StalePostSubmitPriceIsNotKeptOrCompletedAndNeverResubmitted(){var c=new Client{Stale=true};PriceCutPlan? saved=null;var first=await Run(c,checkpoint:p=>saved=p);Assert.Equal(RowStatus.NeedsReview,first.Status);Assert.True(first.Retryable);c.Calls.Clear();var retry=await Run(c,saved);Assert.Equal(RowStatus.NeedsReview,retry.Status);Assert.DoesNotContain("save",c.Calls);Assert.DoesNotContain("exit",c.Calls);}
 [Fact] public async Task SharedIdentityMustContainExactSku(){var c=new Client();c.Product=c.Product with{SharedSkus=["SKU-B","SKU-C"]};Assert.Equal(RowStatus.NeedsReview,(await Run(c)).Status);Assert.DoesNotContain("prepare",c.Calls);Assert.DoesNotContain("save",c.Calls);Assert.DoesNotContain("exit",c.Calls);}
 [Fact] public async Task SharedDifferentTargetsDoNotExitOrChangeParent(){var c=new Client();c.Product=c.Product with{SharedSkus=["SKU-A","SKU-B"]};var r=await Run(c);Assert.Equal(RowStatus.NeedsReview,r.Status);Assert.Contains("共享链接",r.Message);Assert.DoesNotContain("prepare",c.Calls);Assert.DoesNotContain("save",c.Calls);Assert.DoesNotContain("exit",c.Calls);}
 [Theory][InlineData(false)][InlineData(true)] public async Task RealStoreAcceptsOnlyOrderedBoundIncomeStages(bool capped)
 {
  var dir=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString());try{var storage=new JobStore(dir);var v=StorageTests.Snapshot(1);v.Rows[0]=v.Rows[0] with{Input=Input()};var j=storage.Create(v,ExecutionMode.PriceCut,true,true,true,true);storage.TryStart(j.Summary.Id);var row=storage.ClaimNext(j.Summary.Id)!;var c=new Client{NormalNet=61,Capped=capped};var result=await Run(c,checkpoint:p=>storage.SavePriceCutPlan(j.Summary.Id,row.Id,p));Assert.Equal(RowStatus.Succeeded,result.Status);Assert.Equal("income-exit",storage.Get(j.Summary.Id).Rows[0].PriceCut!.Stage);Assert.Contains("exit",c.Calls);if(capped)Assert.Contains("exit-ordinary",c.Calls);var final=storage.Get(j.Summary.Id).Rows[0].PriceCut!;Assert.Throws<AppException>(()=>storage.SavePriceCutPlan(j.Summary.Id,row.Id,final));Assert.Throws<AppException>(()=>storage.SavePriceCutPlan(j.Summary.Id,row.Id,final with{IncomeSubsidyNet=100}));}finally{Directory.Delete(dir,true);}
 }
}

